/**
 * First-version endpoint allowlist.
 *
 * The remote bridge turns a paired device into an owner-equivalent Peer. That
 * makes this list the real permission boundary: only the endpoints below are
 * ever forwarded to the remote Gateway. No generic invoke, service reflection,
 * credential, terminal, file-open or plugin-management route is exposed.
 */

/** @typedef {'unary'|'stream'} EndpointMode */

/** @type {ReadonlyMap<string, EndpointMode>} */
export const ALLOWED_ENDPOINTS = new Map([
  // Official forwarded event stream and its owner-only answer RPC.
  ['$events', 'stream'],
  ['$events/result', 'unary'],

  // Session surface used by the official session UI. These are the exact
  // endpoints generated by @deepseek-ai/dsh-api-session-controller 0.2.1-rc.3.
  ['fileReferences/list', 'unary'],
  ['skills/list', 'unary'],
  ['session/attachment', 'unary'],
  ['session/cancel', 'unary'],
  ['session/canOpenWorkspacePath', 'unary'],
  ['session/control', 'stream'],
  ['session/create', 'unary'],
  ['session/follow', 'stream'],
  ['session/fork', 'unary'],
  ['session/initializeDefaultModel', 'unary'],
  ['session/list', 'unary'],
  ['session/modelCatalog', 'unary'],
  ['session/openWorkspacePath', 'unary'],
  ['session/page', 'unary'],
  ['session/projections', 'unary'],
  ['session/prompt', 'unary'],
  ['session/rename', 'unary'],
  ['session/search', 'unary'],
  ['session/selectModel', 'unary'],
  ['session/updateQueue', 'unary'],
  ['session/workspacePathApplications', 'unary'],

  // Workspace surface used by the official sidebar and workspace picker.
  // Mutations are explicit official actions on the paired Host; v1 does not
  // expose a generic service-reflection or filesystem surface.
  ['directoryPicker/createDirectory', 'unary'],
  ['directoryPicker/list', 'unary'],
  ['directoryPicker/pick', 'unary'],
  ['workspace/archiveSession', 'unary'],
  ['workspace/create', 'unary'],
  ['workspace/delete', 'unary'],
  ['workspace/follow', 'stream'],
  ['workspace/initializeDefault', 'unary'],
  ['workspace/insertBefore', 'unary'],
  ['workspace/insertSessionBefore', 'unary'],
  ['workspace/pinSession', 'unary'],
  ['workspace/rename', 'unary'],
  ['workspace/unarchiveSession', 'unary'],
  ['workspace/unpinSession', 'unary'],

  // Host-initiated questions in the official conversation UI. `attachWait` is
  // the live timed claim opened by the answer card; `answer` steers the reply
  // back into the same Agent/session. Both are scoped by agentId on the wire.
  ['userQuestions/answer', 'unary'],
  ['userQuestions/attachWait', 'stream'],

  // Read-only menus used by the official composer/session creation UI.
  ['permissionPresets/catalog', 'unary'],
  ['agentPresets/list', 'unary'],
  ['agentPresets/read', 'unary'],
  ['commands/list', 'unary'],
]);

/** @type {readonly string[]} */
export const ALLOWED_ENDPOINT_NAMES = Object.freeze([...ALLOWED_ENDPOINTS.keys()].sort());

/**
 * @param {unknown} endpoint
 * @param {EndpointMode} mode
 * @returns {boolean}
 */
export function isAllowed(endpoint, mode) {
  if (typeof endpoint !== 'string') return false;
  const allowed = ALLOWED_ENDPOINTS.get(endpoint);
  return allowed !== undefined && allowed === mode;
}

/**
 * Explicitly denied prefixes, used for diagnostics and documentation.
 * @param {string} endpoint
 */
export function isDeniedNamespace(endpoint) {
  if (typeof endpoint !== 'string' || ALLOWED_ENDPOINTS.has(endpoint)) return false;
  return /^(credentials|settings|terminal|workspaceFiles|fileUploads|plugins|pluginManager|dynamicCordis|inspector|configEditor|hmr|account|llm|subagents|jobs|schedules|goals|messageFeedback|agentTeams|workflowEngine|ptcRuntime|officeToPdf)\//.test(endpoint);
}
